{"command":"cat << 'EOF' > printer.go
package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"text/tabwriter"
	"os"
)

type ListEntry struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP"`
	Host    string `json:"Host"`
}

func printEntries(entries []ListEntry, format string) {
	if len(entries) == 0 {
		return
	}

	if format == "json" {
		b, _ := json.Marshal(entries)
		fmt.Println(string(b))
		return
	}

	if format == "raw" {
		w := tabwriter.NewWriter(os.Stdout, 0, 0, 1, ' ', 0)
		fmt.Fprintln(w, "PROFILE\tSTATUS\tIP\tDOMAIN")
		for _, e := range entries {
			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", e.Profile, e.Status, e.IP, e.Host)
		}
		w.Flush()
		return
	}

	// Calculate widths
	maxProf := 7
	maxStat := 6
	maxIP := 2
	maxDom := 6

	for _, e := range entries {
		if len(e.Profile) > maxProf { maxProf = len(e.Profile) }
		if len(e.Status) > maxStat { maxStat = len(e.Status) }
		if len(e.IP) > maxIP { maxIP = len(e.IP) }
		if len(e.Host) > maxDom { maxDom = len(e.Host) }
	}

	drawLine := func(char string) {
		if format == "markdown" {
			fmt.Printf("|-%s-|-%s-|-%s-|-%s-|\n",
				strings.Repeat("-", maxProf),
				strings.Repeat("-", maxStat),
				strings.Repeat("-", maxIP),
				strings.Repeat("-", maxDom))
		} else {
			fmt.Printf("+-%s-+-%s-+-%s-+-%s-+\n",
				strings.Repeat("-", maxProf),
				strings.Repeat("-", maxStat),
				strings.Repeat("-", maxIP),
				strings.Repeat("-", maxDom))
		}
	}

	center := func(s string, w int) string {
		pad := w - len(s)
		left := pad / 2
		right := pad - left
		return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
	}

	left := func(s string, w int) string {
		return s + strings.Repeat(" ", w-len(s))
	}

	if format != "markdown" {
		drawLine("+")
	}

	fmt.Printf("| %s | %s | %s | %s |\n",
		center("PROFILE", maxProf),
		center("STATUS", maxStat),
		center("IP", maxIP),
		center("DOMAIN", maxDom))

	if format == "markdown" {
		drawLine("-")
	} else {
		drawLine("+")
	}

	for i, e := range entries {
		fmt.Printf("| %s | %s | %s | %s |\n",
			left(e.Profile, maxProf),
			left(e.Status, maxStat),
			left(e.IP, maxIP),
			left(e.Host, maxDom))

		// If the next entry is a different profile and we are in table mode, draw line?
		// Wait, looking at our previous tests, there's a divider between default and other profiles!
		if format == "table" && i < len(entries)-1 {
			if e.Profile == "default" && entries[i+1].Profile != "default" {
				drawLine("+")
			}
		}
	}

	if format == "table" {
		drawLine("+")
	}
}
EOF
"}

