{"command":"cat << 'EOF' > main.go
package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"strings"
	"time"
)

var hostFile = "/etc/hosts"
var outFormat = "table"
var quiet = false
var raw = false

func main() {
	args := os.Args[1:]
	var cmds []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--host-file" && i+1 < len(args) {
			hostFile = args[i+1]
			i++
		} else if arg == "-o" || arg == "--out" {
			if i+1 < len(args) {
				outFormat = args[i+1]
				i++
			}
		} else if arg == "-q" || arg == "--quiet" {
			quiet = true
		} else if arg == "--raw" {
			raw = true
			outFormat = "raw"
		} else if strings.HasPrefix(arg, "-") {
			// Ignore unhandled global or command flags
			if arg == "-f" || arg == "--from" || arg == "--path" {
				i++ // skip value
			}
		} else {
			cmds = append(cmds, arg)
		}
	}

	if len(cmds) == 0 {
		fmt.Println("hostctl dev")
		return
	}

	cmd := cmds[0]

	if !quiet && cmd != "status" {
		fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFile)
	}

	hf, err := parseHosts(hostFile)
	if err != nil {
		fmt.Println("Error parsing hosts file:", err)
		os.Exit(1)
	}

	switch cmd {
	case "list":
		handleList(hf, cmds[1:])
	case "add":
		handleAdd(hf, args, cmds[1:])
	case "disable":
		handleDisable(hf, cmds[1:])
	case "enable":
		handleEnable(hf, cmds[1:])
	case "remove", "rm":
		handleRemove(hf, cmds[1:])
	case "backup":
		handleBackup(args)
	case "status":
		handleStatus(hf)
	default:
		// Unsupported
	}
}

func handleList(hf *HostsFile, args []string) {
	filter := "all"
	if len(args) > 0 {
		filter = args[0]
	}

	var entries []ListEntry

	// Add default profile
	if filter == "all" || filter == "enabled" {
		for _, dl := range hf.DefaultLines {
			if dl.IsEntry {
				entries = append(entries, ListEntry{Profile: "default", Status: "on", IP: dl.IP, Host: dl.Domain})
			}
		}
	}

	for _, name := range hf.ProfileNames {
		p := hf.Profiles[name]
		if filter == "enabled" && p.Status != "on" { continue }
		if filter == "disabled" && p.Status != "off" { continue }

		for _, e := range p.Entries {
			entries = append(entries, ListEntry{Profile: p.Name, Status: p.Status, IP: e.IP, Host: e.Domain})
		}
	}

	printEntries(entries, outFormat)
}

func getFlagValue(args []string, flag1, flag2 string) string {
	for i, arg := range args {
		if (arg == flag1 || arg == flag2) && i+1 < len(args) {
			return args[i+1]
		}
	}
	return ""
}

func handleAdd(hf *HostsFile, fullArgs []string, args []string) {
	if len(args) == 0 {
		return
	}
	subCmd := args[0]
	if subCmd == "domains" || subCmd == "domain" {
		// add domains
		if len(args) < 3 { return }
		profile := args[1]
		ip := getFlagValue(fullArgs, "--ip", "")
		if ip == "" { ip = "127.0.0.1" }

		p, exists := hf.Profiles[profile]
		if !exists {
			p = &Profile{Name: profile, Status: "on"}
			hf.Profiles[profile] = p
			hf.ProfileNames = append(hf.ProfileNames, profile)
		}

		domains := args[2:]
		for _, d := range domains {
			p.Entries = append(p.Entries, Entry{IP: ip, Domain: d})
		}

		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet {
			fmt.Printf("[✔] Domains '%s, %s' added.\n\n", ip, strings.Join(domains, ", "))
			handleList(hf, nil)
		}
		return
	}

	// Add profile from file
	profile := args[0]
	fromFile := getFlagValue(fullArgs, "-f", "--from")
	if fromFile == "" { return }

	b, err := ioutil.ReadFile(fromFile)
	if err == nil {
		p, exists := hf.Profiles[profile]
		if !exists {
			p = &Profile{Name: profile, Status: "on"}
			hf.Profiles[profile] = p
			hf.ProfileNames = append(hf.ProfileNames, profile)
		}
		lines := strings.Split(string(b), "\n")
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") { continue }
			fields := strings.Fields(line)
			if len(fields) >= 2 {
				p.Entries = append(p.Entries, Entry{IP: fields[0], Domain: fields[1]})
			}
		}
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet {
			handleList(hf, nil)
		}
	}
}

func handleDisable(hf *HostsFile, args []string) {
	if len(args) == 0 { return }
	profile := args[0]
	if p, ok := hf.Profiles[profile]; ok {
		p.Status = "off"
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet {
			handleList(hf, nil)
		}
	}
}

func handleEnable(hf *HostsFile, args []string) {
	if len(args) == 0 { return }
	profile := args[0]
	if p, ok := hf.Profiles[profile]; ok {
		p.Status = "on"
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet {
			handleList(hf, nil)
		}
	}
}

func handleRemove(hf *HostsFile, args []string) {
	if len(args) == 0 { return }
	if args[0] == "domains" {
		if len(args) < 3 { return }
		profile := args[1]
		domains := args[2:]
		if p, ok := hf.Profiles[profile]; ok {
			var newEntries []Entry
			for _, e := range p.Entries {
				keep := true
				for _, d := range domains {
					if e.Domain == d { keep = false; break }
				}
				if keep { newEntries = append(newEntries, e) }
			}
			p.Entries = newEntries
			ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
			if !quiet {
				fmt.Printf("[✔] Domains '%s' removed.\n\n", strings.Join(domains, ", "))
				handleList(hf, nil)
			}
		}
		return
	}
	profile := args[0]
	if _, ok := hf.Profiles[profile]; ok {
		delete(hf.Profiles, profile)
		var newNames []string
		for _, n := range hf.ProfileNames {
			if n != profile { newNames = append(newNames, n) }
		}
		hf.ProfileNames = newNames
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet {
			fmt.Printf("[✔] Profile(s) '%s' removed.\n\n", profile)
		}
	}
}

func handleBackup(fullArgs []string) {
	path := getFlagValue(fullArgs, "--path", "")
	if path == "" { path = "./" }
	if !strings.HasSuffix(path, "/") { path += "/" }

	now := time.Now().Format("20060102")
	target := path + "my_hosts." + now // wait! earlier it was test_hosts.YYYYMMDD
	// It uses the hostFile base name!
	parts := strings.Split(hostFile, "/")
	baseName := parts[len(parts)-1]
	target = path + baseName + "." + now

	b, _ := ioutil.ReadFile(hostFile)
	ioutil.WriteFile(target, b, 0644)
	if !quiet {
		fmt.Printf("[✔] Backup '%s.%s' created.\n\n", baseName, now)
		// It also lists afterwards
		hf, _ := parseHosts(hostFile)
		handleList(hf, nil)
	}
}

func handleStatus(hf *HostsFile) {
	if !quiet {
		fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFile)
	}
	type StatEntry struct { Profile, Status string }
	var entries []ListEntry
	for _, n := range hf.ProfileNames {
		p := hf.Profiles[n]
		entries = append(entries, ListEntry{Profile: p.Name, Status: p.Status})
	}
	// Status command prints a 2-column table!
	// printEntries handles 4-column, I need to tweak it or write a status printer
}
EOF"}

