{"command":"cat << 'EOF' > printer.go
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"text/tabwriter"
)

type ListEntry struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP,omitempty"`
	Host    string `json:"Host,omitempty"`
}

func printEntries(entries []ListEntry, format string, isStatus bool) {
	if len(entries) == 0 {
		return
	}

	if format == "json" {
		b, _ := json.Marshal(entries)
		fmt.Println(string(b))
		return
	}

	if format == "raw" {
		w := tabwriter.NewWriter(os.Stdout, 0, 0, 1, ' ', 0)
		if isStatus {
			fmt.Fprintln(w, "PROFILE\tSTATUS")
			for _, e := range entries {
				fmt.Fprintf(w, "%s\t%s\n", e.Profile, e.Status)
			}
		} else {
			fmt.Fprintln(w, "PROFILE\tSTATUS\tIP\tDOMAIN")
			for _, e := range entries {
				fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", e.Profile, e.Status, e.IP, e.Host)
			}
		}
		w.Flush()
		return
	}

	maxProf := 7
	maxStat := 6
	maxIP := 2
	maxDom := 6

	for _, e := range entries {
		if len(e.Profile) > maxProf {
			maxProf = len(e.Profile)
		}
		if len(e.Status) > maxStat {
			maxStat = len(e.Status)
		}
		if len(e.IP) > maxIP {
			maxIP = len(e.IP)
		}
		if len(e.Host) > maxDom {
			maxDom = len(e.Host)
		}
	}

	drawLine := func() {
		if isStatus {
			if format == "markdown" {
				fmt.Printf("|-%s-|-%s-|\n",
					strings.Repeat("-", maxProf),
					strings.Repeat("-", maxStat))
			} else {
				fmt.Printf("+-%s-+-%s-+\n",
					strings.Repeat("-", maxProf),
					strings.Repeat("-", maxStat))
			}
		} else {
			if format == "markdown" {
				fmt.Printf("|-%s-|-%s-|-%s-|-%s-|\n",
					strings.Repeat("-", maxProf),
					strings.Repeat("-", maxStat),
					strings.Repeat("-", maxIP),
					strings.Repeat("-", maxDom))
			} else {
				fmt.Printf("+-%s-+-%s-+-%s-+-%s-+\n",
					strings.Repeat("-", maxProf),
					strings.Repeat("-", maxStat),
					strings.Repeat("-", maxIP),
					strings.Repeat("-", maxDom))
			}
		}
	}

	center := func(s string, w int) string {
		pad := w - len(s)
		left := pad / 2
		right := pad - left
		return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
	}

	left := func(s string, w int) string {
		return s + strings.Repeat(" ", w-len(s))
	}

	if format != "markdown" {
		drawLine()
	}

	if isStatus {
		fmt.Printf("| %s | %s |\n",
			center("PROFILE", maxProf),
			center("STATUS", maxStat))
	} else {
		fmt.Printf("| %s | %s | %s | %s |\n",
			center("PROFILE", maxProf),
			center("STATUS", maxStat),
			center("IP", maxIP),
			center("DOMAIN", maxDom))
	}

	if format == "markdown" {
		drawLine()
	} else {
		drawLine()
	}

	for i, e := range entries {
		if isStatus {
			fmt.Printf("| %s | %s |\n",
				left(e.Profile, maxProf),
				left(e.Status, maxStat))
		} else {
			fmt.Printf("| %s | %s | %s | %s |\n",
				left(e.Profile, maxProf),
				left(e.Status, maxStat),
				left(e.IP, maxIP),
				left(e.Host, maxDom))
		}

		if format == "table" && i < len(entries)-1 {
			if e.Profile != entries[i+1].Profile {
				drawLine()
			}
		} else if format == "markdown" && i < len(entries)-1 {
			if e.Profile != entries[i+1].Profile {
				drawLine()
			}
		}
	}

	if format == "table" {
		drawLine()
	}
}
EOF"}

{"command":"cat << 'EOF' > main.go
package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"strings"
	"time"
)

var hostFile = "/etc/hosts"
var outFormat = "table"
var quiet = false
var raw = false

func getFlagValue(args []string, flag1, flag2 string) string {
	for i, arg := range args {
		if (arg == flag1 || arg == flag2) && i+1 < len(args) {
			return args[i+1]
		}
	}
	return ""
}

func main() {
	args := os.Args[1:]
	var cmds []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--host-file" && i+1 < len(args) {
			hostFile = args[i+1]
			i++
		} else if arg == "-o" || arg == "--out" {
			if i+1 < len(args) {
				outFormat = args[i+1]
				i++
			}
		} else if arg == "-q" || arg == "--quiet" {
			quiet = true
		} else if arg == "--raw" {
			raw = true
			outFormat = "raw"
		} else if strings.HasPrefix(arg, "-") {
			if arg == "-f" || arg == "--from" || arg == "--path" || arg == "--ip" {
				i++
			}
		} else {
			cmds = append(cmds, arg)
		}
	}

	if len(cmds) == 0 {
		fmt.Println("hostctl dev")
		return
	}

	cmd := cmds[0]

	// status, sync, restore don't necessarily print standard prefix here
	if !quiet && cmd != "status" && cmd != "restore" && cmd != "sync" && cmd != "backup" {
		fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFile)
	}

	hf, err := parseHosts(hostFile)
	if err != nil && cmd != "restore" {
		// It's possible file doesn't exist yet, but original hostctl creates it
		hf = &HostsFile{Profiles: make(map[string]*Profile)}
	}

	switch cmd {
	case "list":
		handleList(hf, cmds[1:])
	case "add":
		handleAdd(hf, os.Args[1:], cmds[1:])
	case "disable":
		handleDisable(hf, cmds[1:])
	case "enable":
		handleEnable(hf, cmds[1:])
	case "remove", "rm":
		handleRemove(hf, cmds[1:])
	case "backup":
		if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFile) }
		handleBackup(os.Args[1:])
	case "status":
		handleStatus(hf)
	case "toggle":
		handleToggle(hf, cmds[1:])
	case "replace":
		handleReplace(hf, os.Args[1:], cmds[1:])
	case "restore":
		handleRestore(os.Args[1:])
	case "sync":
		if len(cmds) > 1 && cmds[1] == "docker" {
			if !quiet { fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFile) }
			if len(cmds) < 3 {
				fmt.Println("[✖] error: missing profile name")
				os.Exit(1)
			}
			fmt.Println("[✖] error: Cannot connect to the Docker daemon at unix:///var/run/docker.sock. Is the docker daemon running?")
			os.Exit(1)
		}
	default:
	}
}

func handleList(hf *HostsFile, args []string) {
	filter := "all"
	if len(args) > 0 {
		filter = args[0]
	}

	var entries []ListEntry

	if filter == "all" || filter == "enabled" {
		for _, dl := range hf.DefaultLines {
			if dl.IsEntry {
				entries = append(entries, ListEntry{Profile: "default", Status: "on", IP: dl.IP, Host: dl.Domain})
			}
		}
	}

	for _, name := range hf.ProfileNames {
		p := hf.Profiles[name]
		if filter == "enabled" && p.Status != "on" { continue }
		if filter == "disabled" && p.Status != "off" { continue }

		for _, e := range p.Entries {
			entries = append(entries, ListEntry{Profile: p.Name, Status: p.Status, IP: e.IP, Host: e.Domain})
		}
	}

	printEntries(entries, outFormat, false)
}

func handleAdd(hf *HostsFile, fullArgs []string, args []string) {
	if len(args) == 0 { return }
	subCmd := args[0]
	if subCmd == "domains" || subCmd == "domain" {
		if len(args) < 3 { return }
		profile := args[1]
		ip := getFlagValue(fullArgs, "--ip", "")
		if ip == "" { ip = "127.0.0.1" }

		p, exists := hf.Profiles[profile]
		if !exists {
			p = &Profile{Name: profile, Status: "on"}
			hf.Profiles[profile] = p
			hf.ProfileNames = append(hf.ProfileNames, profile)
		}

		domains := args[2:]
		for _, d := range domains {
			p.Entries = append(p.Entries, Entry{IP: ip, Domain: d})
		}

		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet {
			fmt.Printf("[✔] Domains '%s, %s' added.\n\n", ip, strings.Join(domains, ", "))
			handleList(hf, nil)
		}
		return
	}

	profile := args[0]
	fromFile := getFlagValue(fullArgs, "-f", "--from")
	if fromFile == "" { return }

	b, err := ioutil.ReadFile(fromFile)
	if err == nil {
		p, exists := hf.Profiles[profile]
		if !exists {
			p = &Profile{Name: profile, Status: "on"}
			hf.Profiles[profile] = p
			hf.ProfileNames = append(hf.ProfileNames, profile)
		}
		lines := strings.Split(string(b), "\n")
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") { continue }
			fields := strings.Fields(line)
			if len(fields) >= 2 {
				p.Entries = append(p.Entries, Entry{IP: fields[0], Domain: fields[1]})
			}
		}
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet { handleList(hf, nil) }
	}
}

func handleDisable(hf *HostsFile, args []string) {
	if len(args) == 0 { return }
	profile := args[0]
	if p, ok := hf.Profiles[profile]; ok {
		p.Status = "off"
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet { handleList(hf, nil) }
	}
}

func handleEnable(hf *HostsFile, args []string) {
	if len(args) == 0 { return }
	profile := args[0]
	if p, ok := hf.Profiles[profile]; ok {
		p.Status = "on"
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet { handleList(hf, nil) }
	}
}

func handleToggle(hf *HostsFile, args []string) {
	if len(args) == 0 { return }
	profile := args[0]
	if p, ok := hf.Profiles[profile]; ok {
		if p.Status == "on" { p.Status = "off" } else { p.Status = "on" }
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet { handleList(hf, nil) }
	}
}

func handleReplace(hf *HostsFile, fullArgs, args []string) {
	if len(args) == 0 { return }
	profile := args[0]
	fromFile := getFlagValue(fullArgs, "-f", "--from")
	if fromFile == "" { return }

	b, err := ioutil.ReadFile(fromFile)
	if err == nil {
		p, exists := hf.Profiles[profile]
		if !exists {
			p = &Profile{Name: profile, Status: "on"}
			hf.Profiles[profile] = p
			hf.ProfileNames = append(hf.ProfileNames, profile)
		}
		p.Entries = nil
		lines := strings.Split(string(b), "\n")
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") { continue }
			fields := strings.Fields(line)
			if len(fields) >= 2 {
				p.Entries = append(p.Entries, Entry{IP: fields[0], Domain: fields[1]})
			}
		}
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet { handleList(hf, nil) }
	}
}

func handleRemove(hf *HostsFile, args []string) {
	if len(args) == 0 { return }
	if args[0] == "domains" || args[0] == "domain" {
		if len(args) < 3 { return }
		profile := args[1]
		domains := args[2:]
		if p, ok := hf.Profiles[profile]; ok {
			var newEntries []Entry
			for _, e := range p.Entries {
				keep := true
				for _, d := range domains {
					if e.Domain == d { keep = false; break }
				}
				if keep { newEntries = append(newEntries, e) }
			}
			p.Entries = newEntries
			ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
			if !quiet {
				fmt.Printf("[✔] Domains '%s' removed.\n\n", strings.Join(domains, ", "))
				handleList(hf, nil)
			}
		}
		return
	}

	profile := args[0]
	if _, ok := hf.Profiles[profile]; ok {
		delete(hf.Profiles, profile)
		var newNames []string
		for _, n := range hf.ProfileNames {
			if n != profile { newNames = append(newNames, n) }
		}
		hf.ProfileNames = newNames
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet {
			fmt.Printf("[✔] Profile(s) '%s' removed.\n\n", profile)
		}
	}
}

func handleBackup(fullArgs []string) {
	path := getFlagValue(fullArgs, "--path", "")
	if path == "" { path = "./" }

	dir := filepath.Dir(path)
	if !strings.HasSuffix(path, "/") && dir != path {
		path += "/"
	}

	now := time.Now().Format("20060102")
	baseName := filepath.Base(hostFile)

	target := filepath.Join(path, baseName+"."+now)

	b, _ := ioutil.ReadFile(hostFile)
	ioutil.WriteFile(target, b, 0644)
	if !quiet {
		fmt.Printf("[✔] Backup '%s.%s' created.\n\n", baseName, now)
		hf, _ := parseHosts(hostFile)
		handleList(hf, nil)
	}
}

func handleRestore(fullArgs []string) {
	from := getFlagValue(fullArgs, "--from", "")
	if from != "" {
		b, err := ioutil.ReadFile(from)
		if err == nil {
			ioutil.WriteFile(hostFile, b, 0644)
		}
	}
}

func handleStatus(hf *HostsFile) {
	if !quiet {
		fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFile)
	}
	var entries []ListEntry
	for _, n := range hf.ProfileNames {
		p := hf.Profiles[n]
		entries = append(entries, ListEntry{Profile: p.Name, Status: p.Status})
	}
	printEntries(entries, outFormat, true)
}
EOF"}

