func handleBackup(fullArgs []string) {
	path := getFlagValue(fullArgs, "--path", "")
	if path == "" { path = "./" }

	dir := filepath.Dir(path)
	if !strings.HasSuffix(path, "/") && dir != path {
		path += "/"
	}

	now := time.Now().Format("20060102")
	baseName := filepath.Base(hostFile)

	target := filepath.Join(path, baseName+"."+now)

