)

type DefaultLine struct {
	IsEntry bool
	Line    string
	IP      string
	Domain  string
}

type Profile struct {
	Name    string
	Status  string
	Entries []Entry
}

type Entry struct {
	IP     string
	Domain string
}

type HostsFile struct {
	DefaultLines []DefaultLine
	Profiles     map[string]*Profile
	ProfileNames []string
}

func parseHosts(filename string) (*HostsFile, error) {
	b, err := ioutil.ReadFile(filename)
	if err != nil {
		return nil, err
	}
	lines := strings.Split(string(b), "\n")

	hf := &HostsFile{
		Profiles: make(map[string]*Profile),
	}

	mode := "default"
	var currentProfile *Profile

	for i := 0; i < len(lines); i++ {
		line := lines[i]
		trimmed := strings.TrimSpace(line)

		if strings.HasPrefix(trimmed, "##################################################################") {
			i += 2
			mode = "profiles"
			continue
		}

		if mode == "default" {
			if trimmed == "" || strings.HasPrefix(trimmed, "#") {
				hf.DefaultLines = append(hf.DefaultLines, DefaultLine{IsEntry: false, Line: line})
			} else {
				fields := strings.Fields(trimmed)
				if len(fields) >= 2 {
					hf.DefaultLines = append(hf.DefaultLines, DefaultLine{
						IsEntry: true,
						IP:      fields[0],
						Domain:  fields[1],
					})
				} else {
					hf.DefaultLines = append(hf.DefaultLines, DefaultLine{IsEntry: false, Line: line})
				}
			}
		} else if mode == "profiles" {
			if strings.HasPrefix(trimmed, "# profile.") {
				parts := strings.Fields(trimmed)
				if len(parts) >= 3 {
					statusPart := parts[1]
					status := "off"
					if strings.HasSuffix(statusPart, ".on") {
						status = "on"
					}
					name := parts[2]
					currentProfile = &Profile{Name: name, Status: status}
					hf.Profiles[name] = currentProfile
					hf.ProfileNames = append(hf.ProfileNames, name)
				}
			} else if trimmed == "# end" {
				currentProfile = nil
			} else if currentProfile != nil && trimmed != "" {
				lineToParse := trimmed
				if currentProfile.Status == "off" && strings.HasPrefix(lineToParse, "#") {
					lineToParse = strings.TrimSpace(lineToParse[1:])
				}
				fields := strings.Fields(lineToParse)
				if len(fields) >= 2 {
					currentProfile.Entries = append(currentProfile.Entries, Entry{IP: fields[0], Domain: fields[1]})
				}
			}
		}
	}
	return hf, nil
}

func renderHosts(hf *HostsFile) string {
	var out []string

	for _, dl := range hf.DefaultLines {
		if dl.IsEntry {
			out = append(out, dl.IP+" "+dl.Domain)
		} else {
			out = append(out, dl.Line)
		}
	}

	if len(hf.ProfileNames) > 0 {
		// trim trailing empty lines from default section before adding banner
		for len(out) > 0 && out[len(out)-1] == "" {
			out = out[:len(out)-1]
		}
		out = append(out, "")
		out = append(out, "##################################################################")
		out = append(out, "# Content under this line is handled by hostctl. DO NOT EDIT.")
		out = append(out, "##################################################################")
		out = append(out, "")

		for _, name := range hf.ProfileNames {
			p := hf.Profiles[name]
			statusStr := "off"
			if p.Status == "on" {
				statusStr = "on"
			}
			out = append(out, "# profile."+statusStr+" "+p.Name)
			for _, e := range p.Entries {
				line := e.IP + " " + e.Domain
				if p.Status == "off" {
					line = "# " + line
				}
				out = append(out, line)
			}
			out = append(out, "# end")
		}
	} else {
		// if no profiles, trim trailing empty lines from default section
		for len(out) > 0 && out[len(out)-1] == "" {
			out = out[:len(out)-1]
		}
	}

	return strings.Join(out, "\n") + "\n"
}
EOF"}

