func handleReplace(hf *HostsFile, fullArgs, args []string) {
	if len(args) == 0 { return }
	profile := args[0]
	fromFile := getFlagValue(fullArgs, "-f", "--from")
	if fromFile == "" { return }

	b, err := ioutil.ReadFile(fromFile)
	if err == nil {
		p, exists := hf.Profiles[profile]
		if !exists {
			p = &Profile{Name: profile, Status: "on"}
			hf.Profiles[profile] = p
			hf.ProfileNames = append(hf.ProfileNames, profile)
		}
		p.Entries = nil
		lines := strings.Split(string(b), "\n")
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") { continue }
			fields := strings.Fields(line)
			if len(fields) >= 2 {
				p.Entries = append(p.Entries, Entry{IP: fields[0], Domain: fields[1]})
			}
		}
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet { handleList(hf, []string{"all"}) }
	}
}

func handleRemove(hf *HostsFile, args []string) {
	if len(args) == 0 { return }
	if args[0] == "domains" || args[0] == "domain" {
		if len(args) < 3 { return }
		profile := args[1]
		domains := args[2:]
		if p, ok := hf.Profiles[profile]; ok {
			var newEntries []Entry
			for _, e := range p.Entries {
				keep := true
				for _, d := range domains {
					if e.Domain == d { keep = false; break }
				}
				if keep { newEntries = append(newEntries, e) }
			}
			p.Entries = newEntries
			ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
			if !quiet {
				fmt.Printf("[✔] Domains '%s' removed.\n\n", strings.Join(domains, ", "))
				handleList(hf, []string{"all"})
			}
		}
		return
	}

	profile := args[0]
	if _, ok := hf.Profiles[profile]; ok {
		delete(hf.Profiles, profile)
		var newNames []string
		for _, n := range hf.ProfileNames {
			if n != profile { newNames = append(newNames, n) }
		}
		hf.ProfileNames = newNames
		ioutil.WriteFile(hostFile, []byte(renderHosts(hf)), 0644)
		if !quiet {
			fmt.Printf("[✔] Profile(s) '%s' removed.\n\n", profile)
		}
	}
}

func handleBackup(fullArgs []string) {
	path := getFlagValue(fullArgs, "--path", "")
	if path == "" { path = "./" }

	dir := filepath.Dir(path)
	if !strings.HasSuffix(path, "/") && dir != path {
		path += "/"
	}

	now := time.Now().Format("20060102")
	baseName := filepath.Base(hostFile)

	target := filepath.Join(path, baseName+"."+now)

	b, _ := ioutil.ReadFile(hostFile)
	ioutil.WriteFile(target, b, 0644)
	if !quiet {
		fmt.Printf("[✔] Backup '%s.%s' created.\n\n", baseName, now)
		hf, _ := parseHosts(hostFile)
		handleList(hf, []string{"all"})
	}
}

func handleRestore(fullArgs []string) {
	from := getFlagValue(fullArgs, "--from", "")
	if from != "" {
		b, err := ioutil.ReadFile(from)
		if err == nil {
			ioutil.WriteFile(hostFile, b, 0644)
		}
	}
}

func handleStatus(hf *HostsFile) {
	if !quiet {
		fmt.Printf("[ℹ] Using hosts file: %s\n\n", hostFile)
	}
	var entries []ListEntry
	for _, n := range hf.ProfileNames {
		p := hf.Profiles[n]
		entries = append(entries, ListEntry{Profile: p.Name, Status: p.Status})
	}
	printEntries(entries, outFormat, true)
}
